    workedExample: { title: "Dos compras, una moneda compartida", scenario: "Ejemplo simulado: compra de 20.000 EUR en EUR/USD a 1,10 y de 10.000 GBP en GBP/USD a 1,25. Se estudian pérdidas al stop de 40 y 60 EUR y 30 EUR extra en un choque común; cuenta de 10.000 EUR.", steps: ["Exposición USD simplificada: −20.000 × 1,10 = −22.000 USD y −10.000 × 1,25 = −12.500 USD.", "Total de exposición corta a USD = −34.500 USD, además de las exposiciones largas a EUR y GBP.", "Pérdida condicionada = 40 + 60 + 30 = 130 EUR = 1,3 % del capital."], conclusion: "La cantidad de símbolos no elimina la concentración frente al dólar. El escenario agregado incluye ejecución adversa." },
    commonMistakes: [{ mistake: "Dividir una apuesta entre cinco pares la diversifica automáticamente.", correction: "Examinar monedas y factores compartidos." }, { mistake: "Una correlación baja garantiza pérdidas pequeñas en una crisis.", correction: "Añadir pruebas de estrés y admitir cambios de dependencia." }], summary: ["Descompón pares en monedas y factores.", "La correlación depende de datos, ventana y frecuencia.", "El límite agregado complementa los presupuestos individuales."], relatedConcepts: ["Concentración", "Correlación", "Riesgo de base", "Exposición nominal"], sources: [concentration, plan, forex],
    diagram: { title: "La moneda común", nodes: ["Largo EUR/USD: −22.000 USD", "Largo GBP/USD: −12.500 USD", "Total: −34.500 USD", "Choque compartido", "Control del presupuesto agregado"], caption: "Los nominales revelan dirección compartida; la pérdida necesita además movimiento, costes y conversión." },
